window.LQ=window.LQ||{};
Object.assign(window.LQ,{
"p18m1":[
 {id:"p18m1q1", q:"A table WorkOrders(wo_id PRIMARY KEY, tech_id, tech_name, tech_phone, site_address) stores one row per work order. tech_name and tech_phone are determined by tech_id. Which normal form does this table violate?", options:["First normal form, because tech_name repeats on many rows","Second normal form, because tech_name depends on only part of the key","Third normal form, because tech_name depends on tech_id, a non-key column","None, because every column ultimately depends on wo_id"], answer:2, why:"wo_id determines tech_id, and tech_id determines tech_name and tech_phone: a transitive dependency, which 3NF forbids. 2NF concerns partial dependency on a composite key, and wo_id is a single column, so 2NF cannot be the problem. Move technician facts to a technicians table."},
 {id:"p18m1q2", q:"A clinic keeps Appointments(appt_id, appt_date, patient_id, patient_name, patient_phone). A patient's new phone number is typed into one of her 12 appointment rows, and reports now show two different numbers for her. Which anomaly is this, and what removes it?", options:["An insert anomaly; add an index on patient_id","An update anomaly; store the phone once, in a patients table","A delete anomaly; add ON DELETE CASCADE to the patient foreign key","An update anomaly; add a CHECK constraint on patient_phone"], answer:1, why:"The same fact is stored on 12 rows, so an update that misses some rows leaves the data contradicting itself: an update anomaly. Storing the phone once in patients (3NF) makes disagreement impossible. A constraint on the repeated column cannot stop the duplication that causes the problem."},
 {id:"p18m1q3", q:"Each technician can hold many certifications, each certification is held by many technicians, and every holding has its own expiry date. Which design stores this correctly?", options:["technicians(tech_id, name, cert_ids, expiry_dates) with comma-separated lists","technicians(tech_id, name, cert_id, expires_on) with cert_id as a foreign key","certifications(cert_id, name, expires_on) plus a junction table tech_certs(tech_id, cert_id)","tech_certs(tech_id, cert_id, expires_on) keyed on (tech_id, cert_id), both foreign keys"], answer:3, why:"Many-to-many needs a junction table keyed by the pair of foreign keys, and an attribute of the pairing (this technician's expiry for this certification) belongs on the junction row. expires_on in certifications would force one expiry for every holder; comma lists break 1NF."},
 {id:"p18m1q4", q:"You are designing customers, referenced by orders, invoices and support tickets. A colleague proposes email as the primary key because it is already unique. Customers do change their email addresses. What does the lesson recommend?", options:["A generated identity column as primary key, with email declared UNIQUE NOT NULL","Keep email as the primary key and add ON UPDATE CASCADE to every foreign key","A composite primary key of (email, phone) so that either one can change","No uniqueness rule on email in the database; enforce it in application code"], answer:0, why:"Natural keys change, and every referencing row would have to change with them. A surrogate key keeps identity stable while UNIQUE on email still enforces the business rule. Enforcing uniqueness only in application code is tempting, but concurrent application checks race; constraints do not."},
 {id:"p18m1q5", q:"deliveries.driver_id references drivers. A delivery may be created before anyone is assigned to it, but once assigned it must point to a real driver. How should driver_id be declared?", options:["NOT NULL REFERENCES drivers, storing 0 until a driver is assigned","A plain integer with no foreign key, checked by the application at assignment time","Nullable REFERENCES drivers, so it may be empty but never point to a missing driver","NOT NULL REFERENCES drivers ON DELETE SET NULL, so removed drivers clear it"], answer:2, why:"A nullable foreign key models an optional relationship: NULL is allowed, and any non-NULL value must exist in drivers. A 0 sentinel either fails the foreign key or forces a fake driver row. NOT NULL combined with SET NULL contradicts itself, so deleting a driver would fail."}
],
"p18m2":[
 {id:"p18m2q1", q:"payment.amount holds the values 10, 20, NULL and 30 in four rows. What do COUNT(*), COUNT(amount) and AVG(amount) return?", options:["4, 4 and 15","4, 3 and 20","3, 3 and 20","4, 3 and 15"], answer:1, why:"COUNT(*) counts rows (4); COUNT(amount) counts non-NULL values (3); AVG ignores NULL, so it is 60 / 3 = 20. The tempting 15 treats NULL as zero and divides by 4, but NULL means unknown, not zero."},
 {id:"p18m2q2", q:"This query raises an error: SELECT customer_id, SUM(amount) AS total FROM payment WHERE total > 100 GROUP BY customer_id; Which change fixes it?", options:["Add total to the GROUP BY list so the alias becomes available","Put the alias in quotes so WHERE can find it","Move WHERE total > 100 below GROUP BY, keeping the alias","Replace WHERE with HAVING SUM(amount) > 100 after GROUP BY"], answer:3, why:"WHERE runs before GROUP BY and SELECT, so neither the alias total nor any aggregate exists yet. Filtering groups by an aggregate is HAVING's job. Moving WHERE after GROUP BY is not valid SQL, and quoting the alias does not change when it is computed."},
 {id:"p18m2q3", q:"Goal: customers with no rentals on or after 2024-01-01. Query: SELECT c.customer_id FROM customer c LEFT JOIN rental r ON r.customer_id = c.customer_id WHERE r.rental_date >= '2024-01-01' AND r.rental_id IS NULL; It always returns zero rows. Why?", options:["The date test belongs in ON; in WHERE it is unknown for unmatched rows and drops them","An anti-join needs a RIGHT JOIN so the rental side keeps its unmatched rows","IS NULL must be written = NULL for the unmatched rows to compare as equal","The query needs GROUP BY c.customer_id before IS NULL can be evaluated per customer"], answer:0, why:"Unmatched customers get NULL in every rental column, so the date comparison is unknown and WHERE discards them; rows that pass have a rental_id, so IS NULL fails. Moving the date into ON limits which rentals match, leaving NULL-extended rows for IS NULL. NOT EXISTS also works."},
 {id:"p18m2q4", q:"To list the top two films per category you write: SELECT category, title, ROW_NUMBER() OVER (PARTITION BY category ORDER BY rentals DESC) AS rn FROM film_stats WHERE rn <= 2; It fails. What is the correct fix?", options:["Replace ROW_NUMBER() with RANK(), which WHERE is allowed to filter","Change WHERE rn <= 2 to HAVING rn <= 2, which runs after grouping","Compute rn in a CTE, then filter WHERE rn <= 2 in the outer query","Add GROUP BY category so the window result can be filtered"], answer:2, why:"Window functions are evaluated with SELECT, after WHERE and HAVING have run, so rn does not exist when either filter applies. The two-step idiom computes the row number in a CTE and filters outside it. HAVING filters groups, not window results, so it fails the same way."},
 {id:"p18m2q5", q:"A PostgreSQL report runs SELECT first_name || ' ' || last_name FROM customer LIMIT 5; You must run it on MySQL with default settings. Which version returns the full names?", options:["SELECT first_name || ' ' || last_name FROM customer LIMIT 5;","SELECT TOP 5 CONCAT(first_name, ' ', last_name) FROM customer;","SELECT CONCAT(first_name, ' ', last_name) FROM customer WHERE ROWNUM <= 5;","SELECT CONCAT(first_name, ' ', last_name) FROM customer LIMIT 5;"], answer:3, why:"MySQL supports LIMIT, but by default || means logical OR, so the unchanged query returns 0s and 1s instead of names; CONCAT is required. TOP is SQL Server syntax and ROWNUM is Oracle's legacy row limiter, so neither runs on MySQL."}
],
"p18m3":[
 {id:"p18m3q1", q:"In PostgreSQL you run BEGIN; CREATE TABLE import_tmp (id int, footage numeric); then INSERT 5,000 rows into it, spot a mistake, and run ROLLBACK. What is left afterward?", options:["An empty import_tmp table, because CREATE TABLE committed implicitly","Nothing: import_tmp does not exist and the 5,000 rows are gone","import_tmp with 5,000 rows, because ROLLBACK only undoes the last statement","An error at CREATE TABLE, because DDL cannot run inside a transaction"], answer:1, why:"PostgreSQL's DDL is transactional, so the CREATE TABLE and the INSERTs roll back together and the table never existed. The empty-table answer describes Oracle or MySQL, which commit implicitly around DDL and would keep the table while rolling back the later inserts."},
 {id:"p18m3q2", q:"A loader inserts 60,000 rows into PostgreSQL over one connection in autocommit mode, one INSERT per row. Each commit's WAL flush takes about 1 ms on this SSD. What is the approximate floor on run time, and the fix?", options:["About 60 seconds; wrap the rows in one transaction so there is one flush","About 60 milliseconds; the SSD absorbs the flushes, so nothing needs changing","About 6 seconds; raise shared_buffers so the rows stay in memory","About 60 seconds; switch to Serializable so commits are grouped"], answer:0, why:"Durability requires a WAL fsync before each COMMIT returns, so 60,000 commits × 1 ms ≈ 60 seconds of waiting. One transaction pays for one flush at the end. shared_buffers caches data pages but cannot skip the flush durability demands at every commit; isolation level does not change it either."},
 {id:"p18m3q3", q:"Two users submit the signup form with the same email within a millisecond. users.email is declared UNIQUE. One insert succeeds; the other fails with SQLSTATE 23505. What does that mean, and how should the application respond?", options:["A serialization failure; retry the insert with backoff until it succeeds","A deadlock; the engine picked one transaction as victim, so rerun it","A unique violation; the constraint caught the race, so report the email as taken","A foreign key violation; create the missing parent row, then retry the insert"], answer:2, why:"23505 is unique_violation: the constraint, checked inside the write's transaction, stopped the second insert even though both requests passed any application-side check. Retrying would fail forever; the right response is an 'already registered' message. Retry is correct for 40001 and 40P01, not 23505."},
 {id:"p18m3q4", q:"Rule: at least one of two shift supervisors must stay on duty. In PostgreSQL under Repeatable Read, transactions A and B each count 2 on duty, each sets a different supervisor's row to off duty, and both try to commit. What happens?", options:["B's commit fails with 40001, because Repeatable Read forbids this anomaly","B's UPDATE waits for A, then sees one supervisor left and stops","Both commit, and the rule holds because each saw a consistent snapshot","Both commit and no one is on duty; Serializable would abort one with 40001"], answer:3, why:"This is write skew: the transactions update different rows, so Repeatable Read sees no write conflict and both commit, breaking the invariant. Repeatable Read raises 40001 only when two transactions update the same row. Serializable Snapshot Isolation detects the dependency and aborts one for retry."},
 {id:"p18m3q5", q:"Job A updates account 7 then account 3; job B, running concurrently, updates account 3 then account 7. Every few hours one of them fails with SQLSTATE 40P01. What fix does the lesson prescribe?", options:["Raise deadlock_timeout to 30 seconds so the waits resolve on their own","Lock accounts in one consistent order (lowest id first) and retry on 40P01","Run both jobs at Read Uncommitted so their updates take no row locks","Add CHECK (balance >= 0) so that conflicting updates are rejected before they lock"], answer:1, why:"40P01 is a deadlock: each job holds one row lock and waits for the other's. Locking rows in the same order everywhere makes the cycle impossible, and a retry handles any victim. Raising deadlock_timeout only delays detection, because a lock cycle never resolves by waiting."}
],
"p18m4":[
 {id:"p18m4q1", q:"The hottest query is: SELECT * FROM orders WHERE tenant_id = $1 AND created_at >= $2 ORDER BY created_at LIMIT 50; Which single index serves it best?", options:["A B-tree on (created_at, tenant_id)","Separate B-trees on tenant_id and on created_at","A hash index on tenant_id","A B-tree on (tenant_id, created_at)"], answer:3, why:"Equality column first, range column second: the B-tree jumps to the tenant's entries, which are already sorted by created_at, so the range and the ORDER BY come straight from the index. Leading with created_at scans every tenant's rows in the range; a hash index cannot serve ranges or ordering."},
 {id:"p18m4q2", q:"A table holds 20 million rows that take about 200 bytes each on disk, including tuple headers. Roughly how many 8 kB pages is that, and how long does a full sequential scan take at 2 GB/s?", options:["About 490,000 pages; about 2 seconds","About 49,000 pages; about 0.2 seconds","About 2.5 million pages; about 10 seconds","About 490,000 pages; about 20 milliseconds"], answer:0, why:"20 million × 200 B = 4 GB; 4,000,000,000 / 8,192 ≈ 488,000 pages; 4 GB at 2 GB/s ≈ 2 seconds. Twenty milliseconds is the territory of an index lookup touching a handful of pages, not a scan that must read every page of the heap."},
 {id:"p18m4q3", q:"Right after a bulk load, a report is slow. EXPLAIN ANALYZE shows a Nested Loop whose outer input is: Seq Scan on shipments (cost=0.00..35.50 rows=12 width=40) (actual time=0.02..910.4 rows=480000 loops=1). Most likely cause and fix?", options:["work_mem is too small; raise it so the scan fits in memory","random_page_cost is too low; raise it so an index is chosen","Statistics predate the load; run ANALYZE shipments","The table is bloated; run VACUUM FULL to remove dead tuples"], answer:2, why:"Estimated 12 rows versus 480,000 actual is a 40,000× mismatch, the signature of stale statistics: the planner believes the table is nearly empty, so a nested loop looked cheap. ANALYZE refreshes the statistics. work_mem matters when sorts or hashes spill to disk, which this plan does not show."},
 {id:"p18m4q4", q:"An API lists events 50 at a time with ORDER BY id LIMIT 50 OFFSET n. Page 1 takes 2 ms; page 4,000 takes 450 ms. What change keeps every page fast?", options:["Add a second B-tree index on id so OFFSET can skip rows quickly","Keyset pagination: WHERE id > last_seen_id ORDER BY id LIMIT 50","Raise work_mem so the skipped rows are sorted in memory","Wrap the query in a CTE marked MATERIALIZED so pages are cached"], answer:1, why:"Page 4,000 uses OFFSET 199,950, so the engine reads and discards about 200,000 rows before returning 50; cost grows with page number. Keyset pagination seeks straight to the last id seen through the primary-key index, so every page costs a few page reads. Another index cannot change what OFFSET discards."},
 {id:"p18m4q5", q:"orders.status has a B-tree index, and 85% of rows have status = 'shipped'. EXPLAIN for WHERE status = 'shipped' shows a Seq Scan, and a colleague says the index is broken. What is the correct reading?", options:["The planner is right: for 85% of rows, one ordered scan is cheaper than index probes","The index is corrupt and must be rebuilt with REINDEX before it is used again","Statistics are stale; ANALYZE will make the planner switch to the index","B-tree indexes cannot serve equality on text columns; a hash index is needed"], answer:0, why:"The planner compares estimated costs; above roughly 5–10% selectivity a sequential scan usually wins because random page reads cost more than reading the heap in order. The index still serves rare values such as 'open'. Stale statistics would show estimate-versus-actual mismatches, and nothing here suggests that."}
],
"p18m5":[
 {id:"p18m5q1", q:"pg_hba.conf, in order: (1) hostssl shop app_rw 10.0.0.0/24 scram-sha-256; (2) host all all 10.0.0.0/24 reject; (3) host shop all 10.0.0.0/8 scram-sha-256. app_rw connects to shop from 10.0.0.25 over plain TCP without TLS. What happens?", options:["Accepted with a password, because line 1 matches any TCP from that subnet","Accepted with a password, because line 3 names the shop database","Rejected, because line 1 requires TLS and line 2 is the first match","Accepted without a password, because no line requires one"], answer:2, why:"pg_hba.conf is read top to bottom and the first matching line wins. hostssl matches only TLS connections, so this plain TCP connection skips line 1 and matches line 2, reject. Line 3 would also match, but it is never reached."},
 {id:"p18m5q2", q:"A Grafana dashboard needs read access to the shop database, including tables created next month. Which setup follows least privilege?", options:["Connect as postgres and switch the dashboard's data source to read-only","Reuse the application's app_rw role, which already has working grants on every table","Make the dashboard's role the owner of schema public so it sees every table","A login role with only SELECT (plus CONNECT and USAGE) and default SELECT privileges"], answer:3, why:"Least privilege means a dedicated role with exactly SELECT, and ALTER DEFAULT PRIVILEGES extends it to future tables. app_rw can write, so a stolen dashboard password could change data. A client-side read-only switch is not authorization: the postgres superuser can still do anything."},
 {id:"p18m5q3", q:"A shop runs pg_dump at 01:00 every night and nothing else. At 23:30 a developer runs DELETE FROM orders without a WHERE. How much order data is lost, and what would bound the loss to about a minute?", options:["None; pg_dump keeps recording every change until the next dump is taken","About 22.5 hours; a base backup plus WAL archiving (archive_timeout = 60) for PITR","About 22.5 hours; an asynchronous streaming standby, which still holds the deleted rows","About 30 minutes; pg_dumpall instead of pg_dump, since it also captures WAL"], answer:1, why:"A logical dump is one point in time, so everything after 01:00 is gone: 22.5 hours. PITR replays archived WAL to just before the DELETE, and archive_timeout = 60 caps unarchived WAL at a minute. A standby replays the DELETE within seconds; it is for availability, not recovery."},
 {id:"p18m5q4", q:"A payments database must not lose a single committed transaction if the primary server is destroyed, and the team accepts one extra network round trip per commit. Which configuration delivers that?", options:["Streaming replication with the standby listed in synchronous_standby_names","Asynchronous streaming replication with a replication slot on the primary","Logical replication of all payment tables to a second server in another rack","A nightly pg_basebackup copied to off-site storage and tested monthly"], answer:0, why:"With synchronous replication, COMMIT does not return until the standby acknowledges the WAL, so every committed transaction exists on two machines. Asynchronous replication, even with a slot, can lose the last few transactions; the slot only keeps WAL from being removed before the standby consumes it."},
 {id:"p18m5q5", q:"A report page lets users pick the sort column, and the code appends the request's sort parameter after ORDER BY. You learn that ORDER BY $1 binds a value, not a column name. What is the correct defense?", options:["Escape quote characters in the parameter before appending it to the query","Strip spaces, quotes and semicolons from the parameter before appending it","Map the choice to a fixed allowlist of column names and reject anything else","Rely on the web application firewall to block unusual column names"], answer:2, why:"Identifiers cannot be bound parameters, so the structural defense is an allowlist: input only selects among column names you wrote and never becomes SQL text (quote_ident is the other option). Escaping and stripping characters are filters with a long record of bypasses; a WAF is defense in depth, not the fix."}
],
"p18m6":[
 {id:"p18m6q1", q:"A store keeps N = 5 replicas of each key. Every read must overlap the latest write, and both reads and writes must keep working with any 2 replicas down. Which setting meets both requirements?", options:["W = 2, R = 3","W = 3, R = 3","W = 5, R = 1","W = 2, R = 2"], answer:1, why:"Overlap requires W + R > N: 3 + 3 = 6 > 5, and with 2 nodes down 3 remain, enough for both quorums. W = 2, R = 3 sums to exactly 5, so a read can miss the write. W = 5 overlaps, but every write fails as soon as one replica is down."},
 {id:"p18m6q2", q:"A three-node etcd cluster (a CP system) is split by a network partition: node C is cut off from A and B. A client connected only to C tries to write. What happens?", options:["The write succeeds on C and is merged with A and B when the partition heals","All three nodes refuse writes until the partition heals","The write succeeds, because partition tolerance means every node keeps answering","The write is refused, since C cannot reach a majority; A and B keep serving"], answer:3, why:"During a partition a CP system gives up availability where it cannot guarantee consistency: C alone is a minority and must refuse, while the A–B majority keeps accepting writes. Accepting on C and merging later is AP behavior, as in Cassandra, and risks conflicting values."},
 {id:"p18m6q3", q:"A fintech team must interactively find accounts linked through shared devices, cards and addresses up to six hops away. Which store fits this access pattern best?", options:["A graph database such as Neo4j, queried with Cypher","Redis, keeping each account's links in a set","Cassandra, with one denormalized table per query","Elasticsearch, indexing every account as a document"], answer:0, why:"The question is path-shaped: graph stores use index-free adjacency, so each hop follows stored relationships cheaply, and Cypher expresses variable-length patterns directly. Redis sets would need a round trip per hop and traversal in application code; Cassandra has no joins and suits known per-partition queries."},
 {id:"p18m6q4", q:"In SQLite you run CREATE TABLE readings(id INTEGER PRIMARY KEY, footage INTEGER); then INSERT INTO readings(footage) VALUES ('about 500'); The table was not declared STRICT. What happens?", options:["The insert fails with a datatype mismatch error for footage","The insert succeeds and stores the integer 500, dropping the text","The insert succeeds and stores the text 'about 500' unchanged","The insert succeeds but stores NULL, since the value cannot convert"], answer:2, why:"SQLite's typing is dynamic by default: a column declared INTEGER only expresses a preference, and text that cannot be converted is stored as text. Declaring the table STRICT (3.37+) makes the same insert fail. Expecting an error is the PostgreSQL habit, where declared types are enforced."},
 {id:"p18m6q5", q:"Auditing your own company's servers, you find a Redis instance listening on 0.0.0.0:6379 with no authentication. Which remediation matches the lesson's hardening rules?", options:["Move it to a non-standard port such as 16379 so scanners miss it","Bind it privately, require authentication and TLS, and firewall the port","Leave it as is, since Redis contents are only a disposable cache","Enable RDB snapshots so any tampered or deleted data can be restored"], answer:1, why:"The hardening rule is the same for every store: no listener on public interfaces, authentication and TLS on, port firewalled. A different port is obscurity that scanners defeat quickly. Disposable contents do not make exposure safe: an open Redis leaks sessions and lets anyone change or delete keys."}
],
"p18m7":[
 {id:"p18m7q1", q:"A fact table has 500 million rows and 40 columns of 8 bytes each. A query reads 4 of those columns, and the column store compresses them 8×. Roughly how much data does the column store read?", options:["About 160 GB","About 20 GB","About 16 GB","About 2 GB"], answer:3, why:"Row-oriented, the table is 500M × 40 × 8 B = 160 GB. A column store reads only 4 columns: 500M × 4 × 8 B = 16 GB, and 8× compression brings that to about 2 GB, roughly 1 second versus 80 seconds at 2 GB/s. 16 GB forgets compression."},
 {id:"p18m7q2", q:"Sales rep Dana moves from the West region to East on July 1. Executives want her first-half revenue to stay under West and later revenue under East. How should dim_salesperson handle the move?", options:["Overwrite the region in her existing dimension row (Type 1)","Add a new row with its own surrogate key, valid from July 1 (Type 2)","Update the region on all her past fact rows so totals agree","Key the dimension by employee number so both regions share one row"], answer:1, why:"Type 2 preserves history: old facts keep pointing at the West row's surrogate key, new facts get the East row's key. Type 1 suits typo corrections but would silently move all her past revenue to East. Surrogate keys are what allow two rows for one person."},
 {id:"p18m7q3", q:"fact_sales is declared at the grain 'one row per order line'. Which proposed column does NOT belong in the fact table?", options:["customer_city","quantity","product_key","net_revenue"], answer:0, why:"Fact rows hold numeric measures (quantity, net_revenue) and foreign keys to dimensions (product_key). customer_city describes the customer, so it belongs in dim_customer, stored once and used for filtering and grouping through the join. Repeating it on every order line bloats the one table that is big."},
 {id:"p18m7q4", q:"Each morning an analyst runs a three-year revenue-by-region query against the production PostgreSQL. During that hour checkouts slow down and dead tuples pile up. What does the lesson recommend?", options:["Add a B-tree index on every column the analyst filters on","Run the query at Serializable so it cannot disturb other sessions","Copy the data into a columnar warehouse and run the query there","Raise shared_buffers until three years of orders fit in memory"], answer:2, why:"OLTP and OLAP want opposite storage. The long scan evicts the checkout working set from cache, and its long transaction holds back VACUUM, so dead tuples accumulate. A warehouse lets analysts scan freely without touching the system that takes money. Serializable adds conflict checks; it does not reduce I/O."},
 {id:"p18m7q5", q:"A nightly ELT job appends yesterday's sales to the warehouse. A scheduler glitch runs it twice one night, and the dashboard shows yesterday's revenue doubled. What property is the pipeline missing?", options:["Streaming: events should be processed within seconds of arrival","Columnar storage: the fact table should be stored as Parquet","Normalization: the fact table should be split into 3NF tables","Idempotency: a re-run should replace the day's rows, not append them"], answer:3, why:"An idempotent load gives the same result however many times it runs, for example by deleting and reloading the day's partition or merging on a unique key. Appending blindly duplicates whatever the first run wrote. Streaming changes latency, not correctness on re-runs."}
]
});
Object.assign(window.LQ,{
"p19m1":[
 {id:"p19m1q1", q:"Over 25 working days a team made 50 production deployments, and 2 caused an incident or rollback. Median lead time from merge to production was 6 hours; median time to restore service after a failed deployment was 3 hours. Against the elite band, which metric lags?", options:["Deployment frequency","Change lead time","Change fail rate","Failed deployment recovery time"], answer:3, why:"Frequency is 50 ÷ 25 = 2 per day (elite), lead time of 6 hours is under a day (elite), and change fail rate 2 ÷ 50 = 4% is within the elite 5%. Recovery of 3 hours misses the elite bar of under one hour, so fast rollback is the next investment."},
 {id:"p19m1q2", q:"A team's pipeline builds and tests every merge in 10 minutes and deploys are one command, yet median lead time is 9 days. The Git log shows merged changes waiting for a weekly change-approval meeting. Which change does the lesson's reasoning point to?", options:["Buy faster CI runners to cut the 10-minute build and test time","Batch more changes into each weekly release to use the meeting well","Automate the approval checks and gate production on a canary","Add a second staging environment for extra verification"], answer:2, why:"Lead time is dominated by the manual gate, not by build or deploy mechanics, so a faster build saves minutes out of days. Turning the approval criteria into automated tests and a canary gate removes the wait. Bigger batches make each release riskier and lengthen lead time further."},
 {id:"p19m1q3", q:"A new checkout flow must be in production this week, but marketing wants it visible only to 5% of Texas users starting next month, and the team must be able to turn it off within seconds if errors spike, without a deploy. Which technique fits?", options:["A feature flag evaluated per user, region and percentage","A canary deployment sending 5% of traffic to the new version","A blue-green deployment with a traffic switch","A long-lived release branch merged next month"], answer:0, why:"A feature flag separates deploying from releasing: the code ships dark now, is enabled later for 5% of Texas users, and is switched off in seconds without a deploy. A canary splits traffic between versions during a rollout; it is not a business-timed, per-region release control."},
 {id:"p19m1q4", q:"Production is managed by Argo CD with automatic sync. During a traffic spike an engineer runs kubectl scale deployment web --replicas=10, while Git still says replicas: 4. What happens next, and what is the GitOps way to scale?", options:["The cluster keeps 10, because the live state takes priority over Git","The agent reconciles back to 4; the change should be a commit to the Git repository","Argo CD writes replicas: 10 back into Git so the repository matches the cluster","The Deployment is deleted and recreated because it no longer matches Git"], answer:1, why:"GitOps agents pull desired state from Git and continuously reconcile reality to it, so a manual change is drift and gets reverted. Scaling durably means committing the new replica count (or an autoscaler), which also leaves an audit trail. Agents do not write live state back into Git."},
 {id:"p19m1q5", q:"An app writes logs to /var/log/app/app.log inside its container and keeps user sessions in process memory. After scaling to three replicas on Kubernetes, users are randomly logged out and kubectl logs shows nothing. Which two twelve-factor rules does it break?", options:["Config in the environment and port binding","Dev/prod parity and disposability","Logs as event streams and stateless processes","Declared dependencies and build/release/run separation"], answer:2, why:"Twelve-factor apps write logs to stdout as an event stream, which is what kubectl logs reads, and keep processes stateless, storing sessions in a backing service such as Redis. In-memory sessions break once a second replica receives a user's next request. Config and port binding do not explain these symptoms."}
],
"p19m2":[
 {id:"p19m2q1", q:"Dockerfile: FROM python:3.13-slim, WORKDIR /app, COPY . ., RUN pip install -r requirements.txt, CMD python app.py. You change one line of app.py and rebuild. What happens, and what is the fix?", options:["Only the CMD layer rebuilds, because pip's layer is cached by its instruction text","COPY . . and the pip install after it rerun; install requirements before copying the source","Every layer rebuilds, including FROM, because the build context as a whole changed","Nothing rebuilds until requirements.txt changes, because BuildKit tracks file dependencies"], answer:1, why:"BuildKit reuses a layer only when its instruction and inputs are unchanged and every earlier layer was reused. Editing app.py changes the input of COPY . ., invalidating it and every later step, including the slow pip install. Copying requirements.txt and installing first keeps that layer cached. CMD is metadata, not a layer."},
 {id:"p19m2q2", q:"A Dockerfile step writes a registry token to /root/.netrc to download a private package, and the next RUN step deletes the file. The image is then pushed to a public repository. Is the token exposed?", options:["No; the later rm removed the file from every layer of the image","No; registries encrypt layers, so only the final filesystem is visible","Yes; the earlier layer keeps it: rotate the token and use a build secret","Yes, but only to someone who runs the container with --privileged"], answer:2, why:"Every layer is an immutable archive kept in the image, so the file still exists in the layer that wrote it, visible with docker history or dive. Build secrets never enter a layer, and a multi-stage build leaves the builder's layers behind. Because the token was published, it must be revoked."},
 {id:"p19m2q3", q:"In a Compose project, web and db are two services on the project's default network. web is configured with DATABASE_HOST=localhost and cannot connect to PostgreSQL. What is wrong?", options:["In web, localhost means web itself; connect to the service name db instead","db must publish port 5432 to the host before other containers can reach it","Containers can only reach each other when both use network_mode: host","db needs --privileged so it can accept connections from another container"], answer:0, why:"Each container has its own net namespace, so localhost inside web points at web itself. On a user-defined network such as Compose's, Docker's embedded DNS resolves service names, so db:5432 works without publishing anything. Publishing a port exposes it on the host; containers on the same network do not need it."},
 {id:"p19m2q4", q:"A Kubernetes manifest references ghcr.io/acme/api:latest. Nobody changed the manifest, but after a node restart some Pods ran a different build and failed. Which change prevents a repeat?", options:["Switch to a version tag such as :1.4, since version tags cannot be moved","Add a HEALTHCHECK so the previous build is kept when a new one fails","Pull from Docker Hub instead, where tags never change","Pin the image by digest, ghcr.io/acme/api@sha256:…, in the manifest"], answer:3, why:"Tags are mutable pointers: :latest, and :1.4 just as easily, can be re-pointed by any push, so a node pulling again can get different content. A digest names exact content and can never change, which is why production manifests pin digests. Docker Hub tags are mutable too."},
 {id:"p19m2q5", q:"Your Python service needs a compiled wheel built against glibc, and security wants no shell or package manager in the runtime image. Which approach fits the lesson?", options:["python:3.13 as a single stage, since it already includes the compiler toolchain","Build in a full Debian image, then copy the result into a matching distroless image","python:3.13-alpine, the smallest official base that still has a package manager","python:3.13-slim with a non-root USER app, which removes shell access"], answer:1, why:"A multi-stage build compiles where the toolchain exists and copies only the result into a distroless runtime with no shell or package manager; matching Python versions keeps the copied environment working. Alpine uses musl, which breaks glibc wheels, and a non-root USER limits privileges but leaves the shell and apt in place."}
],
"p19m3":[
 {id:"p19m3q1", q:"A job's matrix lists python 3.11, 3.12 and 3.13 and os ubuntu-latest and windows-latest, with one exclude entry for python 3.11 on windows-latest, and fail-fast: false. How many jobs run, and what happens when one of them fails?", options:["6 jobs; the remaining jobs are cancelled","5 jobs; the remaining jobs are cancelled","5 jobs; the others keep running to completion","3 jobs; each runs both operating systems in sequence"], answer:2, why:"A matrix expands to every combination: 3 × 2 = 6, minus the excluded one = 5 separate jobs. fail-fast defaults to true, which cancels in-progress jobs when one fails; setting it to false lets the rest finish, so you see every combination's result."},
 {id:"p19m3q2", q:"A private repository has used its free minutes. Each push runs a 4-minute Linux job and a 5-minute macOS job, and there are 50 pushes this month. At $0.006 per Linux minute and $0.062 per macOS minute, what do these runs cost?", options:["About $2.70","About $16.70","About $27.90","About $1.20"], answer:1, why:"Linux: 50 × 4 = 200 minutes × $0.006 = $1.20. macOS: 50 × 5 = 250 minutes × $0.062 = $15.50. Total $16.70. Billing every minute at the Linux rate gives $2.70, but macOS minutes cost about ten times more, so macOS jobs belong only where needed."},
 {id:"p19m3q3", q:"A workflow triggered on pull_request contains the step run: echo Checking ${{ github.event.pull_request.title }}. A reviewer flags it as a security bug. Why, and what is the fix?", options:["The title becomes script text before the shell runs; pass it via env: instead","echo mishandles Unicode and emoji in titles; replace it with printf","The title could contain a secret; add it to the masked values before echoing","pull_request events lack the title; switch the trigger to pull_request_target"], answer:0, why:"Expressions are substituted into the script text before the shell parses it, so anyone who can open a pull request can make the title run commands on the runner. Passing it through env: and referencing the quoted variable keeps it data. pull_request_target would be worse: it runs with the base repository's secrets."},
 {id:"p19m3q4", q:"Job build runs python -m build and creates dist/app.whl. Job publish has needs: build, but its ls dist/ step finds nothing. What is wrong?", options:["publish started before build finished, because needs: only sets priority","actions/checkout in publish wiped the workspace and dist/; set clean: false","The cache key changed between jobs; add actions/cache keyed on hashFiles","Jobs run on separate fresh runners; pass dist/ between them as an artifact"], answer:3, why:"needs: orders jobs but does not share a filesystem: each job gets a fresh virtual machine, and only steps within one job share files. Artifacts (upload-artifact, download-artifact) move files between jobs. A cache is for reusable dependencies keyed on lockfiles, not for handing over a build's output."},
 {id:"p19m3q5", q:"You are writing the AWS trust policy for a deploy role that GitHub Actions assumes through OIDC. Which condition is the safest?", options:["Accept any token signed by token.actions.githubusercontent.com, GitHub's issuer","Accept tokens whose subject matches repo:acme/* across the organization","Accept only the subject repo:acme/app:ref:refs/heads/main for this one role","Accept repo:acme/app:*, covering every branch and pull request"], answer:2, why:"The token's claims state exactly which repository and branch is running, so the role should trust only the one subject that needs it. Trusting the issuer alone would let any GitHub repository in the world assume the role; wildcards let every repository, branch or pull request deploy."}
],
"p19m4":[
 {id:"p19m4q1", q:"Someone added the tag CostCenter=42 to a Terraform-managed instance in the AWS console. The team decides to keep the tag. What should you do so the next apply does not undo it?", options:["Run terraform apply; it imports the console tag into state permanently","Add the tag to the resource's tags in code; terraform plan then shows no changes","Run terraform plan -refresh-only; once it reports the drift, the tag is accepted","Delete the state file so Terraform re-reads the instance from AWS"], answer:1, why:"Drift is resolved by enforcing the code or changing the code. To keep the tag, put it in the configuration so desired and actual state match. A refresh-only plan only reports drift; the configuration still lacks the tag, so the next normal apply would remove it."},
 {id:"p19m4q2", q:"You rename aws_instance.web to aws_instance.app in your configuration. terraform plan now shows Plan: 1 to add, 0 to change, 1 to destroy. How do you keep the running instance?", options:["Add lifecycle { prevent_destroy = true } and apply the plan","Run terraform import for aws_instance.app, leaving aws_instance.web in state","Apply the plan; Terraform copies the old instance's disk to the new one","Add a moved block from aws_instance.web to aws_instance.app"], answer:3, why:"State maps resource addresses to real objects, so a renamed address looks like one resource removed and another added. A moved block or state mv re-points the existing object at the new address, and plan shows no changes. prevent_destroy only makes the plan fail; it moves nothing."},
 {id:"p19m4q3", q:"A project with 12 resources keeps its state in a local terraform.tfstate file, and a teammate deletes the file. What does the next terraform plan propose?", options:["Plan: 12 to add; the existing resources are orphaned and keep billing","No changes; Terraform rediscovers the resources from the provider","Plan: 12 to destroy, because the state no longer lists them","Nothing; Terraform refuses to run until state is restored from Git"], answer:0, why:"State is Terraform's only memory of what it owns. Without it every resource block looks new, so plan proposes creating all 12 while the originals keep running and billing. A remote backend with locking and backups prevents this; state never belongs in Git because it can contain secrets."},
 {id:"p19m4q4", q:"A playbook's template task writes /etc/nginx/nginx.conf and notifies the handler 'restart nginx'. You run the playbook a second time and the rendered file is identical to the one on the host. What happens?", options:["The handler runs anyway, because handlers run at the end of every play","The file is rewritten and nginx restarts, since Ansible keeps no state file","The task reports ok, the handler is not notified, and nginx keeps running","The play fails because the destination file already exists"], answer:2, why:"The template module compares the rendered content with the file on the host, so an identical file reports ok, not changed. Handlers run only when a notifying task reports changed, so nginx is not restarted. Ansible has no state file; idempotency comes from each module checking current state."},
 {id:"p19m4q5", q:"Two requirements: the production database must never be destroyed by a mistaken change, and replacing the load balancer's TLS certificate must never leave a moment with no certificate. Which lifecycle rules apply?", options:["ignore_changes on the database; prevent_destroy on the certificate","prevent_destroy on the database; create_before_destroy on the certificate","create_before_destroy on the database; ignore_changes on the certificate","prevent_destroy on both, so neither can ever be replaced"], answer:1, why:"prevent_destroy makes any plan that would destroy the database fail, the guardrail you want there. create_before_destroy builds the replacement certificate before removing the old one, so there is no gap. prevent_destroy on the certificate would block its replacement entirely; ignore_changes only hides changes."}
],
"p19m5":[
 {id:"p19m5q1", q:"After kubectl apply of a Deployment with replicas: 3, kubectl get pods shows three Pods, all Pending with no node assigned, and kubectl describe pod shows no scheduling events at all. Which component is most likely down?", options:["The kubelet on the worker nodes","kube-controller-manager","etcd","kube-scheduler"], answer:3, why:"The Pods exist, so the API server, etcd and the ReplicaSet controller worked. Binding Pods to nodes is the scheduler's job, and a running scheduler that cannot place a Pod records a FailedScheduling event. A dead kubelet would leave Pods already bound to a node but not starting."},
 {id:"p19m5q2", q:"A Pod runs two containers: app, listening on port 8000, and a sidecar that must fetch /metrics from app over HTTP. Which address should the sidecar use?", options:["localhost:8000, since containers in a Pod share one network namespace","The Service's ClusterIP, since containers cannot reach each other directly","The app container's own IP, since the CNI gives each container one","app.default.svc.cluster.local, since CoreDNS names each container"], answer:0, why:"A Pod is one or more containers sharing a single network namespace: the Pod has the IP, and its containers reach each other over localhost. The CNI assigns an IP per Pod, not per container. Going through a Service could land on another replica's app instead of this one."},
 {id:"p19m5q3", q:"A Deployment has replicas: 8 and the default rolling-update settings. During an image update, what is the most Pods that can exist at once, and the fewest that must stay available?", options:["At most 8 Pods; at least 6 available","At most 16 Pods; at least 0 available","At most 10 Pods; at least 6 available","At most 10 Pods; at least 8 available"], answer:2, why:"The defaults are maxSurge 25% and maxUnavailable 25%. 25% of 8 is 2, so the update may run up to 8 + 2 = 10 Pods and may drop to 8 − 2 = 6 available. Keeping all 8 available would require maxUnavailable: 0, which is not the default."},
 {id:"p19m5q4", q:"A teammate moves the database password from a ConfigMap into a Secret and says it is now safe to commit the Secret manifest to Git. Is that right?", options:["Yes; Secret data is encrypted with the cluster's key before it is stored","No; Secret values are only base64-encoded, which anyone can decode","Yes, provided the Secret lives in a dedicated namespace other than default","No; Secrets are stored as plain text only until a Pod first mounts them"], answer:1, why:"Base64 is an encoding anyone can reverse with one command, so a committed Secret manifest publishes the password. Protection comes from RBAC on secrets, encryption at rest in etcd, and keeping raw values out of the repository. Namespaces scope names and permissions; they encrypt nothing."},
 {id:"p19m5q5", q:"On a kubeadm lab cluster on bare metal with no cloud provider, you set a Service to type: LoadBalancer to reach it from your laptop. EXTERNAL-IP stays <pending>. Why, and what is the simplest working alternative?", options:["No cloud controller exists to provision one; use a NodePort on a node's IP","A LoadBalancer Service needs an Ingress in front first; create one for it","clusterIP must be set to None before an external IP is assigned","CoreDNS has not published the name yet; wait for DNS propagation"], answer:0, why:"A LoadBalancer Service asks a cloud controller to put a cloud load balancer in front of a NodePort; with no cloud provider nothing fulfills the request. A NodePort opens a port in 30000–32767 on every node, reachable from the LAN. clusterIP: None makes a headless Service, which is internal only."}
],
"p19m6":[
 {id:"p19m6q1", q:"A node reports 7.6 CPU and 30 GiB allocatable, and Pods already on it request 1.6 CPU and 6 GiB. New Pods each request 1200m CPU and 3 GiB of memory. How many more fit on this node, and which resource binds?", options:["5, limited by CPU","6, limited by CPU","8, limited by memory","10, limited by memory"], answer:0, why:"Remaining capacity is 7.6 − 1.6 = 6.0 CPU and 30 − 6 = 24 GiB. CPU allows 6.0 ÷ 1.2 = 5 Pods; memory allows 24 ÷ 3 = 8. The smaller number wins, so 5 fit and CPU binds. The answer 6 comes from ignoring the requests already scheduled."},
 {id:"p19m6q2", q:"A PVC names the existing StorageClass fast-ssd, which has volumeBindingMode: WaitForFirstConsumer. No Pod uses the claim yet. kubectl get pvc shows Pending, and describe says it is waiting for the first consumer. What does that mean?", options:["The CSI provisioner has crashed and must be restarted before binding","The claim must request ReadWriteMany before any volume can bind to it","The claim is stuck; delete it and recreate it with a smaller size","Expected; the volume is created once a Pod using the claim is scheduled"], answer:3, why:"WaitForFirstConsumer deliberately delays provisioning until a Pod that uses the claim is scheduled, so the disk is created in that Pod's zone. Pending with no consumer is normal. Changing the access mode or size would not help, because nothing has asked for the volume yet."},
 {id:"p19m6q3", q:"The ServiceAccount web in namespace shop must read ConfigMaps in shop and nothing else. Which grant follows least privilege?", options:["A ClusterRole with get and list on configmaps, bound by a ClusterRoleBinding","A Role in shop with get, list, watch on configmaps and a RoleBinding to web","The cluster-admin ClusterRole, bound to web only by a RoleBinding in shop","A Role in shop with all verbs on configmaps and secrets, bound to web"], answer:1, why:"A namespaced Role and RoleBinding confine the grant to shop, and read-only verbs on one resource type match the need. A ClusterRoleBinding would grant the read in every namespace. kubectl auth can-i list configmaps --as=system:serviceaccount:shop:web confirms the result before an auditor asks."},
 {id:"p19m6q4", q:"A kubeadm cluster runs 1.35.4 and must reach 1.37. Which upgrade plan is correct?", options:["Snapshot etcd, run kubeadm upgrade apply v1.37.x on the control plane, then upgrade each node","Upgrade every node's kubelet to 1.37 first, then the control plane, so workloads move early","Snapshot etcd; upgrade the control plane to 1.36, then drain, upgrade and uncordon each node; repeat for 1.37","Upgrade the control plane straight to 1.37 and leave kubelets at 1.35, since they may trail by three minors"], answer:2, why:"kubeadm upgrades one minor version at a time, control plane first, then each node through drain, package upgrade, kubelet restart and uncordon. Kubelets may trail the API server but never lead it, so upgrading them first is invalid. The skew allowance does not let the control plane skip 1.36."},
 {id:"p19m6q5", q:"Every kubectl command against a kubeadm cluster built 13 months ago now fails with 'x509: certificate has expired or is not yet valid'. Which action addresses the cause?", options:["Delete ~/.kube/config and run kubectl again so it negotiates a fresh session","Restart CoreDNS so the API server's name resolves to a valid endpoint again","Upgrade the kubectl client to match the API server's current minor version","Run kubeadm certs renew all on the control plane, then restart its components"], answer:3, why:"kubeadm issues certificates valid for one year, so at 13 months the API server and admin client certificates have expired. Renewing them and restarting the static control plane Pods restores service; refresh admin.conf for kubectl as well. A newer kubectl or a DNS restart cannot make an expired certificate valid."}
],
"p19m7":[
 {id:"p19m7q1", q:"A service has a 99.9% availability SLO over 30 days. In the last hour it served 120,000 requests and 1,200 failed. What is the burn rate, and how does it compare with the lesson's 14.4× paging threshold?", options:["1×; the budget lasts exactly the 30-day window, so no alert is needed","10×; the budget would last about 3 days, below the 14.4× page threshold","10×; a month's budget would be gone in about 3 hours, so page the on-call now","100×; a month's budget would be gone in about 7 hours, so page the on-call now"], answer:1, why:"Error rate is 1,200 ÷ 120,000 = 1%; the SLO allows 0.1%; burn rate is 0.01 ÷ 0.001 = 10×. At 10× the 30-day budget lasts 30 ÷ 10 = 3 days. That warrants a ticket, not a page, under the 14.4× one-hour rule."},
 {id:"p19m7q2", q:"Forty Pods each request 1.5 CPU, but Prometheus shows their P95 usage at 0.3 CPU. At about $0.04 per vCPU-hour and 730 hours a month, roughly how much reserved but unused CPU are you paying for each month?", options:["About $1,400","About $1,750","About $350","About $48"], answer:0, why:"Unused reservation is 40 × (1.5 − 0.3) = 48 vCPU, and 48 × $0.04 × 730 ≈ $1,400 a month. $1,750 is the cost of all 60 requested vCPU, used or not. Right-sizing requests from measured P95 usage recovers most of the waste."},
 {id:"p19m7q3", q:"On-call gets about 30 pages a week for 'node CPU above 80%', and users noticed none of them. Last Tuesday users saw 5% errors for 20 minutes and nothing paged. What does the lesson recommend?", options:["Lower the CPU threshold to 60% so problems are caught earlier","Add a page for every container restart to catch failures at the source","Keep the alerts but send them to email so on-call can sleep","Page on SLO burn rate for error ratio and latency, the symptoms users feel"], answer:3, why:"CPU is a cause, not a symptom: it pages for things users never notice and misses the ones they do. Burn-rate alerts on error ratio and latency fire when the SLO is actually threatened, and every page is actionable. A lower threshold just adds noise that trains people to ignore pages."},
 {id:"p19m7q4", q:"A developer adds a user_id label to http_requests_total so a dashboard can show traffic per user. The service has about 2 million users. What is the main risk?", options:["None; Prometheus compresses label values, so extra series cost nothing","Prometheus will switch that metric from pull to push collection automatically","About 2 million new time series, enough to exhaust Prometheus's memory","rate() stops working on the metric, because label values must be numeric"], answer:2, why:"Every distinct label combination is a separate time series, so a user_id label multiplies the metric by about 2 million and can exhaust Prometheus's memory. Per-user detail belongs in structured logs or traces, which handle high-cardinality fields. Labels never change the pull model."},
 {id:"p19m7q5", q:"A draft postmortem reads: 'Root cause: an engineer ran the migration against production instead of staging. Action: the engineer will be more careful.' What should the review change?", options:["Swap 'human error' for the system gaps that allowed it, and add owned, dated fixes","Name the engineer in the summary so reviewers know whose future changes to double-check","Drop the timeline section, since the root cause is already known and agreed","Keep the document private to the team to avoid embarrassing the engineer"], answer:0, why:"Blameless postmortems ask why the system let a reasonable action cause damage, such as shared staging and production credentials with no confirmation step. Fixes like separate production credentials get an owner and a date. 'Be more careful' changes nothing, and naming people hides information next time."}
]
});
Object.assign(window.LQ,{
"p20m1":[
 {id:"p20m1q1", q:"You change one line in src/loss/calc.py and commit; nothing else in the project changed. How many new objects does Git create for this commit?", options:["1: a diff object holding the changed line","2: one blob for the file and one commit","5: one blob, three trees (root, src, src/loss) and one commit","One object per file in the project, since every commit is a full snapshot"], answer:2, why:"Git stores snapshots by hash: the changed file gets a new blob, each tree on its path (src/loss, src and the root) changes because a child's hash changed, and the commit points at the new root tree. Unchanged files and subtrees are shared by hash, so the snapshot costs five small objects."},
 {id:"p20m1q2", q:"You branch feature from main, make 3 commits on it, and nobody touches main in the meantime. Then you run git switch main and git merge feature. What happens?", options:["Git fast-forwards: main moves to feature's tip and no new commit is created","Git creates a merge commit with two parents","Git replays the 3 commits onto main with new hashes","Git reports a conflict, because both branches contain the same commits"], answer:0, why:"main has not moved, so its tip is an ancestor of feature and Git simply moves the main ref forward: a fast-forward. A two-parent merge commit is needed only when both branches have diverged, and new hashes come from rebase, not merge."},
 {id:"p20m1q3", q:"You edit app.py (change A), run git add app.py, edit app.py again (change B), then run git commit -m 'update'. What does the new commit contain?", options:["Both changes, because commit reads the file from disk","Change B only, because it is the newest version","Nothing; the commit fails because the file changed after staging","Change A only; change B stays in the working tree, unstaged"], answer:3, why:"git add copies a snapshot of the file into the index at that moment, and git commit turns the index into a tree. Change B came after staging, so it shows in git diff but not git diff --staged and is not committed. Stage again or use git commit -a."},
 {id:"p20m1q4", q:"You automate git bisect run ./check.sh across 900 commits. Some commits in the range do not build at all, so the test cannot judge them. What exit code should check.sh return for those commits?", options:["0, so Git treats them as good and moves on","1, so Git treats them as bad","125, so Git skips them","128, so Git records them as untestable and continues"], answer:2, why:"bisect run reads exit 0 as good, 1–127 as bad and 125 as skip. Returning 1 for an unbuildable commit marks it bad and can make Git name the wrong first bad commit; codes above 127 abort the bisect. 900 commits need about 10 test runs."},
 {id:"p20m1q5", q:"secrets.json was committed last week. You now add it to .gitignore, but git status still reports it as modified whenever it changes. What is the correct fix?", options:["Prefix the pattern with a slash so it anchors to the repository root","git rm --cached secrets.json and commit, then rotate the exposed secrets","Run git check-ignore -v secrets.json, which untracks the matching file","Delete .git/index so Git rebuilds it and re-reads .gitignore from scratch"], answer:1, why:".gitignore affects only untracked files; a tracked file stays tracked until git rm --cached removes it from the index. The committed copy remains in history, so its secrets are already exposed and must be rotated. check-ignore only explains which pattern matches; it changes nothing."}
],
"p20m2":[
 {id:"p20m2q1", q:"A field accepts integers from 5 to 20 inclusive. Which set is the 3-value boundary value analysis test set?", options:["4, 5, 20, 21","4, 5, 6, 19, 20, 21","5, 6, 19, 20","0, 5, 12, 20, 25"], answer:1, why:"3-value BVA tests each boundary with its neighbors on both sides: 4, 5, 6 at the lower edge and 19, 20, 21 at the upper. 4, 5, 20, 21 is the 2-value set. The last option samples partitions but skips 4, 6, 19 and 21, the neighbors where off-by-one defects live."},
 {id:"p20m2q2", q:"quantity accepts integers 1–99, and orders of 50 or more get a bulk discount. Considering numeric input only, what is the minimum number of equivalence partitions to test?", options:["3: below 1, 1–99, above 99","2: valid and invalid","6: one per boundary value","4: below 1, 1–49, 50–99, above 99"], answer:3, why:"The program treats 1–49 and 50–99 differently (no discount versus discount), so the valid range splits into two partitions, plus the two invalid ones: four. Treating 1–99 as one class misses the discount rule; boundary values are a separate technique applied at these partitions' edges."},
 {id:"p20m2q3", q:"app/report.py contains from app.client import fetch_rates and calls fetch_rates(). Your test uses patch('app.client.fetch_rates'), yet the real network call still happens. What is the fix?", options:["Patch 'app.report.fetch_rates', where the name is looked up","Patch 'requests.get' globally for the whole test session","Move the import statement inside the test function","Use a session-scoped fixture so the patch is applied earlier"], answer:0, why:"A from-import copies the reference into app.report's namespace at import time, so replacing app.client.fetch_rates does not change the name report already holds. patch must replace the object where it is looked up. Patching requests.get everywhere over-mocks and can hide real failures."},
 {id:"p20m2q4", q:"A suite has 3,000 unit tests at 4 ms each, 150 integration tests at 300 ms and 30 end-to-end browser tests at 30 s, run sequentially. Roughly how long does it take, and where does the time go?", options:["About 1 minute, mostly in the unit tests","About 16 minutes, mostly in the integration tests","About 16 minutes, about 15 of them in the end-to-end tests","About 57 seconds, split evenly across the three tiers"], answer:2, why:"Unit: 3,000 × 4 ms = 12 s. Integration: 150 × 0.3 s = 45 s. End-to-end: 30 × 30 s = 900 s. Total 957 s, about 16 minutes, 94% of it in 30 browser tests. That is the pyramid's point: keep the top thin and run the fast base after every save."},
 {id:"p20m2q5", q:"validate(splices) raises an error if splices > 48. Tests with 10 and 60 give 100% branch coverage. mutmut changes > to >= and every test still passes. Which new test kills this mutant?", options:["A test that 49 is rejected","A test that 0 is accepted","A test that 48 is accepted","A second test that 60 is rejected"], answer:2, why:"With > 48 the value 48 is accepted; with >= 48 it is rejected, so only a test at 48 tells the two versions apart. 49 is rejected by both. Coverage was 100% yet blind to the boundary, which is exactly what mutation testing exposes."}
],
"p20m3":[
 {id:"p20m3q1", q:"export(report, fmt) contains an if/elif chain for csv, json and pdf. Every new format means editing and retesting this function. Which principle is violated, and what is the usual fix?", options:["Open/closed; register exporters in a dict keyed by format name","Liskov substitution; make each format a subclass of the report class","Interface segregation; split the report into many small Protocols","Single responsibility; move export into a singleton ExportManager"], answer:0, why:"Open/closed means extending behavior without modifying working code. A registry mapping format names to exporter functions lets an xlsx exporter arrive in its own module while export() and its tests stay untouched. A singleton manager merely relocates the elif chain and adds global state."},
 {id:"p20m3q2", q:"send_invoice() constructs SmtpClient() internally, so every test run sends real email. Which change follows the lesson?", options:["Make SmtpClient a singleton so the tests share one connection","Add a testing=True parameter that skips the send during test runs","Inject it: send_invoice(invoice, sender), with a fake sender in tests","Patch smtplib at the top of every test module that imports billing"], answer:2, why:"Dependency inversion means depending on an abstraction that is passed in, so tests substitute a fake and production wires the real sender once at the entry point. A boolean flag that switches behavior is a smell, and a singleton is global state that hides the dependency and makes tests order-dependent."},
 {id:"p20m3q3", q:"Your notifier code calls notify(user, message) on every channel object. A new SMS vendor's library offers only send_text(phone_number, body). Which pattern lets the existing code use it unchanged?", options:["Observer","Factory","Singleton","Adapter"], answer:3, why:"An adapter wraps an incompatible interface: SmsAdapter.notify(user, message) calls send_text(user.phone, message), so callers keep using notify. Observer is a tempting name match, but it notifies subscribers of events; it does not translate one interface into another."},
 {id:"p20m3q4", q:"You inherit a 300-line script with no tests and must change how it computes loss totals. What should your first step be?", options:["Rewrite it cleanly from scratch, since that is faster than untangling it","Write characterization tests that pin its current output, bugs included","Apply Extract Function to the loss calculation, then test","Add type hints to every function so mypy can check it"], answer:1, why:"Refactoring needs a safety net, and with no tests the first step is to capture current behavior with characterization tests (Feathers). Each small named refactoring after that is verified. Extracting first is tempting but unprotected, and a rewrite discards behavior nobody knew existed."},
 {id:"p20m3q5", q:"A teammate opens a 1,400-line pull request that mixes a refactor, a new feature and a dependency upgrade. What does the lesson's review guidance suggest?", options:["Approve it, since a change that large cannot be reviewed line by line anyway","Request changes on every style issue before reading the logic","Rewrite it yourself on a new branch and close theirs to save time","Ask for it to be split into three PRs: refactor, feature and upgrade"], answer:3, why:"Changes of a few hundred lines get real reviews; 1,000-line reviews become rubber stamps, and mixing a refactor with behavior changes hides which lines alter behavior. Splitting lets each part be reviewed within a day. Approving unread is exactly the rubber stamp the guidance warns against."}
],
"p20m4":[
 {id:"p20m4q1", q:"Two requests hit DELETE /v1/links/42: (a) one carrying an expired access token, (b) one carrying a valid token whose scope is only links:read. Which status codes should the API return?", options:["(a) 403, (b) 401","(a) 400, (b) 403","(a) 401, (b) 403","(a) 401, (b) 404"], answer:2, why:"401 means the client is not authenticated: an expired token proves nothing about who is calling. 403 means the caller is known but not permitted: the token is valid and lacks the needed scope. Swapping the two is the common mistake, and 404 would falsely claim the link does not exist."},
 {id:"p20m4q2", q:"An API's rate limiter is a token bucket with capacity 100, refilled at 10 tokens per second. A client that has been idle for several minutes suddenly sends 150 requests at once. What happens?", options:["All 150 succeed, because the client was idle for minutes","100 succeed, 50 get 429, then about 10 per second succeed","10 succeed and 140 get 429, because the limit is 10 per second","100 succeed and the other 50 are queued and served automatically"], answer:1, why:"Idle time fills the bucket only to its capacity of 100, so a burst of 100 passes and the other 50 are rejected with 429. After that, tokens arrive at 10 per second, the sustained rate. Rejected requests are not queued; good clients back off with jitter and honor Retry-After."},
 {id:"p20m4q3", q:"A mobile client sends POST /v1/payments, and the connection drops before any response arrives, so the client cannot tell whether the payment was processed. What is the safe retry?", options:["Retry with the same Idempotency-Key so the server replays its stored result","Retry with a new Idempotency-Key so the server treats it as a fresh request","Retry it as a GET, since GET is idempotent and always safe to repeat","Retry in a tight loop with no delay until a 201 Created response arrives"], answer:0, why:"POST is not idempotent, so a blind retry may charge twice. The server stores each Idempotency-Key with its first response and replays it on retries, which makes the retry safe. A new key defeats the mechanism, and retries should use exponential backoff with jitter, not a tight loop."},
 {id:"p20m4q4", q:"Your API accepts RS256 access tokens issued by https://auth.example.com for the audience links-api. Which validation is correct?", options:["Use whatever algorithm the token's header names, so any issuer's tokens work","Verify the signature only, treating exp and aud as informational","Decode the payload and trust it, since base64url data cannot be altered","Pin RS256, verify against the issuer's JWKS key, and check iss, aud and exp"], answer:3, why:"Letting the token choose its algorithm enables alg: none and RS256/HS256 key confusion, so the server pins the algorithm. A valid signature from the right key plus correct iss, aud and an unexpired exp proves the token is genuine, meant for this API and current. Base64url is just encoding."},
 {id:"p20m4q5", q:"Thirty internal microservices exchange high-volume calls. The team wants typed, code-generated contracts and server-side streaming. Which interface style fits best?", options:["gRPC with Protocol Buffers over HTTP/2","GraphQL behind a single endpoint","REST with JSON, described in OpenAPI","REST with JSON at Richardson level 3 (hypermedia)"], answer:0, why:"gRPC sends binary Protocol Buffers over HTTP/2, generates typed clients from a .proto file and supports four streaming modes, which is why the lesson names it for service-to-service calls. REST with OpenAPI is the right default for public APIs; GraphQL suits many clients needing different shapes of one graph."}
],
"p20m5":[
 {id:"p20m5q1", q:"A cache-aside Redis layer has a 95% hit ratio. Hits take 1 ms; misses take 30 ms, including the database read. What is the average read latency, and what share of reads still reach the database?", options:["About 2.5 ms, with 5% of reads reaching the database","About 15.5 ms, with half of reads reaching the database","About 28.6 ms, with 95% of reads reaching the database","About 1 ms, with no reads reaching the database"], answer:0, why:"Weighted average: 0.95 × 1 + 0.05 × 30 = 2.45 ms, and only the 5% of misses reach the database, a 20× reduction in load. 15.5 ms is the plain average of the two latencies, ignoring how often each occurs; 28.6 ms swaps the hit and miss weights."},
 {id:"p20m5q2", q:"A request needs a load balancer (99.99%), an app tier (99.9%) and a database (99.9%), all in series. Roughly what availability and yearly downtime should you expect?", options:["99.9%, the weakest component, about 8.8 hours","About 99.8%, roughly 18 hours","99.99%, the strongest component, about 53 minutes","About 99.97%, roughly 2.6 hours"], answer:1, why:"Dependencies in series multiply: 0.9999 × 0.999 × 0.999 ≈ 0.9979, so about 0.21% of a year, roughly 18 hours, is downtime. The weakest-link answer ignores that each component fails on its own schedule, so their downtimes add up."},
 {id:"p20m5q3", q:"A consumer reads payment events from SQS and credits accounts. Occasionally the same message is processed twice and an account is credited twice. Which fix matches the lesson?", options:["Move to a queue product that guarantees exactly-once delivery end to end","Disable redelivery so each message can reach the consumer only once","Make the consumer idempotent, skipping event IDs it has already recorded","Put a Redis cache in front of the accounts database to absorb repeats"], answer:2, why:"Queues deliver at least once in practice, so duplicates will happen. An idempotent consumer stores each event ID under a unique constraint in the same transaction as the credit, so a repeat is detected and skipped: effectively once. Disabling retries trades duplicates for lost payments."},
 {id:"p20m5q4", q:"In a URL shortener, a user creates a link and clicks it one second later. The redirect lookup goes to an asynchronous read replica and returns 404, though a minute later it works. Which guarantee failed, and what fixes it?", options:["Linearizability; it is impossible to provide, so the 404 must be accepted","Read-your-writes; read a creator's new keys from the primary or cache","Partition tolerance; add a third replica so that a quorum always exists","Monotonic reads; switch the redirect from 302 to 301 so browsers cache it"], answer:1, why:"Asynchronous replication lags, so a replica may not yet hold the write the user just made: a read-your-writes violation. Routing recent creators' reads to the primary, or writing the new key into the cache at creation, closes the gap. The redirect status code affects browser caching, not replication."},
 {id:"p20m5q5", q:"A chat service has groups of up to 500 members and broadcast channels with 2 million followers. Following the lesson's design, how should messages fan out?", options:["Fan out on write for both, so every inbox is precomputed","Fan out on read for both, since writes are the expensive part","Fan out on read for the groups and on write for the broadcast channels","Fan out on write for the groups and on read for the broadcast channels"], answer:3, why:"Writing a copy into each of 500 inboxes is cheap and makes reads fast, so small groups fan out on write. Writing 2 million copies per message would swamp storage and queues, so huge channels store each message once and readers pull it. The reversed option gets both trade-offs backwards."}
],
"p20m6":[
 {id:"p20m6q1", q:"A backlog holds 210 story points. The team's velocity is 30 ± 5 points per two-week Sprint. What forecast should you give?", options:["About 7 Sprints, plausibly 6 to 9 (12 to 18 weeks)","Exactly 7 Sprints, 14 weeks, committed as a delivery date","About 3.5 Sprints, since each Sprint is two weeks long","About 210 hours of work, at one hour per point"], answer:0, why:"210 ÷ 30 = 7 Sprints; the velocity range gives 210 ÷ 35 = 6 to 210 ÷ 25 = 8.4, so 6–9 Sprints, 12–18 weeks. Estimates are forecasts that tighten as you re-plan, never commitments, and points are relative size, so converting them to hours destroys their meaning."},
 {id:"p20m6q2", q:"Your library is at version 2.7.3. The next release adds one backward-compatible function and fixes two bugs. What version is it, and will a project depending on ^2.7.3 pick it up automatically?", options:["2.7.4; yes","3.0.0; no","2.8.3; yes","2.8.0; yes"], answer:3, why:"A backward-compatible feature bumps MINOR and resets PATCH, giving 2.8.0; the fixes ride along. ^2.7.3 means at least 2.7.3 and below 3.0.0, so 2.8.0 is accepted. Releasing it as 2.7.4 would hide a new feature behind a version that promises only fixes."},
 {id:"p20m6q3", q:"Your team runs three-week Sprints. Scaling the one-month maximums proportionally, as the lesson does, what are the timeboxes for Sprint Planning, Sprint Review and Sprint Retrospective?", options:["Planning 8 h, review 4 h, retrospective 3 h","Planning 6 h, review 3 h, retrospective 2.25 h","Planning 4 h, review 2 h, retrospective 1.5 h","Planning 6 h, review 3 h, retrospective 3 h"], answer:1, why:"The maximums for a one-month Sprint are 8, 4 and 3 hours; a three-week Sprint is three quarters of that: 6, 3 and 2.25 hours. The full figures are ceilings for the longest allowed Sprint, and 4, 2 and 1.5 hours fit a two-week Sprint."},
 {id:"p20m6q4", q:"A tool's single 'Guide' page mixes a step-by-step install, a 60-row table of command flags and an essay on why the design uses keyset pagination. Users say they cannot find the flags. What does Diátaxis recommend?", options:["Split it into a how-to guide, a reference page and an explanation","Add a table of contents and anchors to the top of the single page","Turn the whole page into a beginner tutorial with screenshots","Move all of it into the README so everything is in one place"], answer:0, why:"Diátaxis separates documentation by the reader's need: how-to guides for tasks, reference for looking things up, explanation for understanding, tutorials for learning. Mixing them is why the flag table is hard to find. A table of contents helps navigation but leaves three kinds of writing tangled together."},
 {id:"p20m6q5", q:"The team decides to replace Kafka with SQS, reversing ADR-0004 'Use Kafka for events'. What is the correct ADR practice?", options:["Edit ADR-0004 in place so that it describes SQS instead of Kafka","Delete ADR-0004 so nobody follows the outdated decision by mistake","Write a new ADR that supersedes ADR-0004, and mark ADR-0004 superseded","Record the decision in the team chat channel, where everyone will see it"], answer:2, why:"ADRs are an append-only history: a new numbered record explains what changed in the context, and the old one stays, marked superseded, so 'why did we ever use Kafka?' still has an answer. Editing or deleting ADR-0004 erases the reasoning; chat messages do not survive the people in them."}
],
"p20m7":[
 {id:"p20m7q1", q:"A download endpoint serves open(os.path.join(BASE_DIR, filename)), with filename taken from the URL. Which fix does the lesson prescribe?", options:["Strip every '../' sequence from filename before joining the path","URL-decode filename twice so that encoded dots are normalized first","Resolve the joined path and reject it unless it still lies inside BASE_DIR","Return 404 instead of 403 so that probing reveals less about the files"], answer:2, why:"Checking the result is structural: after resolving dot segments and symlinks, a path either lies under BASE_DIR or it does not. Stripping '../' is a filter that crafted input defeats, for example '....//' collapsing back to '../' after one pass, and decoding twice creates new bypasses."},
 {id:"p20m7q2", q:"def can_view(user, doc): try: return acl.check(user.id, doc.id) except Exception: return True. What is wrong with this permission check?", options:["Nothing; returning True keeps the service available during ACL outages","It fails open: any error grants access, so it should log and deny (A10)","It is an injection flaw (A05); the ACL query must be parameterized","It should re-raise so the full stack trace is shown to the user for debugging"], answer:1, why:"An exception in a permission check must mean deny. Here a timeout, a bug or input that makes acl.check throw grants access to anyone: A10's mishandled exceptional condition producing A01's broken access control. Availability never justifies failing open, and stack traces belong in server logs only."},
 {id:"p20m7q3", q:"Which of these log lines follows the lesson's logging rules?", options:["level=warn event=login_failed user=u_8812 ip=203.0.113.9 request_id=7f3a","level=warn event=login_failed user=u_8812 password_tried=Summer2026!","level=info event=payment card=4111111111111111 amount=40.00 request_id=7f3a","level=info event=api_call path=/v1/export?token=eyJhbGciOi... request_id=7f3a"], answer:0, why:"An authentication failure with a correlation ID is exactly what A09 asks you to log. Attempted passwords, full card numbers (PCI DSS) and tokens in URLs turn the log store into a breach target; logs must never hold secrets or more personal data than needed."},
 {id:"p20m7q4", q:"A critical CVE is announced in a widely used logging library. You run 40 services. Which existing practice lets you list the affected services and versions within minutes?", options:["Pinning every third-party GitHub Action to a full commit SHA","A stored SBOM per build, matched against the CVE with Grype","Searching every repository's README for the library's name","Turning on debug logging to see which libraries each service loads"], answer:1, why:"An SBOM is the machine-readable ingredient list of a build, including transitive dependencies and exact versions, so a scanner can check all 40 against the new CVE at once. SHA pinning protects the pipeline from tampered actions, a real A03 control, but it does not inventory what your services ship."},
 {id:"p20m7q5", q:"While building your own app, you notice that a vendor's public API, which is not part of any engagement, returns other customers' records when you change an ID in a request. What does the lesson say to do?", options:["Download a sample of records as proof, then email the vendor","Probe further to measure the full scope before reporting it to the vendor","Publish the details immediately so users can protect themselves","Stop, access nothing more, and report it via coordinated disclosure"], answer:3, why:"You have no authorization, so further access risks violating the CFAA; authorization is written scope, not a hunch. Coordinated disclosure to the vendor or a CVE Numbering Authority, with a customary 90-day window, protects users. Immediate publication hands the flaw to attackers before a fix exists."}
]
});
